package local.velo.bridge;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.util.*;
/** Personal data has one transactional source of truth; legacy preferences are retained. */
public final class AppStore extends SQLiteOpenHelper {
 private static AppStore instance;final Context context;
 public static synchronized AppStore get(Context c){if(instance==null)instance=new AppStore(c.getApplicationContext());return instance;}
 private AppStore(Context c){super(c,"velo-personal.db",null,2);context=c;}
 @Override public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE groups(name TEXT PRIMARY KEY, visible INTEGER NOT NULL DEFAULT 1)");d.execSQL("CREATE TABLE favorites(id TEXT PRIMARY KEY,name TEXT NOT NULL,lat REAL NOT NULL,lon REAL NOT NULL,category TEXT NOT NULL,note TEXT NOT NULL,color INTEGER NOT NULL,updated INTEGER NOT NULL)");d.execSQL("CREATE INDEX favorite_category ON favorites(category)");d.execSQL("CREATE TABLE routes(id TEXT PRIMARY KEY,name TEXT NOT NULL,model TEXT NOT NULL,updated INTEGER NOT NULL,draft TEXT NOT NULL DEFAULT '{}')");d.execSQL("CREATE TABLE rides(id TEXT PRIMARY KEY,name TEXT NOT NULL,started INTEGER NOT NULL,elapsed INTEGER NOT NULL,meters REAL NOT NULL,replay INTEGER NOT NULL,active INTEGER NOT NULL,trace TEXT NOT NULL)");d.execSQL("CREATE TABLE metadata(k TEXT PRIMARY KEY,v TEXT NOT NULL)");for(String n:new String[]{"常用","补水","休息","维修","风景","其他","未分类"}){ContentValues v=new ContentValues();v.put("name",n);d.insertOrThrow("groups",null,v);}}
 @Override public void onUpgrade(SQLiteDatabase d,int old,int next){if(old==1&&next==2){d.execSQL("ALTER TABLE routes ADD COLUMN draft TEXT NOT NULL DEFAULT '{}'");return;}throw new IllegalStateException("需要明确的数据库升级步骤");}
 public synchronized void migrate()throws Exception{SQLiteDatabase d=getWritableDatabase();try(Cursor c=d.rawQuery("SELECT v FROM metadata WHERE k='legacy_pins_v1'",null)){if(c.moveToFirst())return;}
  String raw=context.getSharedPreferences("navigation",0).getString("map_pins","[]");JSONArray rows=new JSONArray(raw);ArrayList<MapPins.Pin> pins=new ArrayList<>();for(int i=0;i<rows.length();i++){JSONObject p=rows.getJSONObject(i);double a=p.getDouble("lat"),b=p.getDouble("lon");validate(p.getString("name"),a,b);pins.add(new MapPins.Pin(p.getString("id"),p.getString("name"),a,b,"未分类","",0xff2d5be3));}
  d.beginTransaction();try{for(MapPins.Pin p:pins)put(d,p);ContentValues v=new ContentValues();v.put("k","legacy_pins_v1");v.put("v",Integer.toString(pins.size()));d.insertOrThrow("metadata",null,v);d.setTransactionSuccessful();}finally{d.endTransaction();}
 }
 static void validate(String name,double lat,double lon){if(name==null||name.trim().isEmpty()||name.trim().length()>60)throw new IllegalArgumentException("名称需为 1～60 个字");if(!Double.isFinite(lat)||!Double.isFinite(lon)||Math.abs(lat)>80||Math.abs(lon)>180)throw new IllegalArgumentException("经纬度无效");}
 static void put(SQLiteDatabase d,MapPins.Pin p){validate(p.name,p.lat,p.lon);ContentValues v=new ContentValues();v.put("id",p.id);v.put("name",p.name.trim());v.put("lat",p.lat);v.put("lon",p.lon);v.put("category",p.group);v.put("note",p.note);v.put("color",p.color);v.put("updated",System.currentTimeMillis());ContentValues g=new ContentValues();g.put("name",p.group);d.insertWithOnConflict("groups",null,g,SQLiteDatabase.CONFLICT_IGNORE);d.insertWithOnConflict("favorites",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 public synchronized void save(MapPins.Pin p){put(getWritableDatabase(),p);}
 public synchronized List<MapPins.Pin> favorites(boolean visible){ArrayList<MapPins.Pin> list=new ArrayList<>();String sql="SELECT f.id,f.name,f.lat,f.lon,f.category,f.note,f.color FROM favorites f"+(visible?" JOIN groups g ON f.category=g.name WHERE g.visible=1":"")+" ORDER BY f.updated DESC,f.name COLLATE NOCASE";try(Cursor c=getReadableDatabase().rawQuery(sql,null)){while(c.moveToNext())list.add(new MapPins.Pin(c.getString(0),c.getString(1),c.getDouble(2),c.getDouble(3),c.getString(4),c.getString(5),c.getInt(6)));}return list;}
 public synchronized void remove(String id){getWritableDatabase().delete("favorites","id=?",new String[]{id});}
 public List<String> groups(){ArrayList<String> a=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT name FROM groups ORDER BY rowid",null)){while(c.moveToNext())a.add(c.getString(0));}return a;}
 public void group(String name,boolean visible){name=name.trim();if(name.isEmpty()||name.length()>30)throw new IllegalArgumentException("分组名称需为 1～30 字");ContentValues v=new ContentValues();v.put("name",name);v.put("visible",visible?1:0);getWritableDatabase().insertWithOnConflict("groups",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 public boolean visible(String name){try(Cursor c=getReadableDatabase().rawQuery("SELECT visible FROM groups WHERE name=?",new String[]{name})){return c.moveToFirst()&&c.getInt(0)==1;}}
 public String exportFavorites()throws Exception{JSONArray a=new JSONArray();for(MapPins.Pin p:favorites(false))a.put(new JSONObject().put("type","Feature").put("id",p.id).put("geometry",new JSONObject().put("type","Point").put("coordinates",new JSONArray().put(p.lon).put(p.lat))).put("properties",new JSONObject().put("name",p.name).put("group",p.group).put("note",p.note).put("color",p.color)));return new JSONObject().put("type","FeatureCollection").put("features",a).toString(2);}
 public static List<MapPins.Pin> readFavorites(String raw)throws Exception{JSONObject o=new JSONObject(raw);if(!"FeatureCollection".equals(o.getString("type")))throw new IllegalArgumentException("请选择 GeoJSON 地点文件");JSONArray a=o.getJSONArray("features");if(a.length()>5000)throw new IllegalArgumentException("一次最多导入 5000 个地点");ArrayList<MapPins.Pin> pins=new ArrayList<>();HashSet<String> ids=new HashSet<>();for(int i=0;i<a.length();i++){JSONObject f=a.getJSONObject(i),g=f.getJSONObject("geometry"),p=f.optJSONObject("properties");if(!"Point".equals(g.getString("type")))throw new IllegalArgumentException("文件包含非地点几何，未导入");if(p==null)p=new JSONObject();JSONArray xy=g.getJSONArray("coordinates");double lon=xy.getDouble(0),lat=xy.getDouble(1);String name=p.optString("name","导入地点"),id=f.optString("id",UUID.randomUUID().toString());validate(name,lat,lon);String group=p.optString("group","其他"),note=p.optString("note","");if(id.length()>100||group.isEmpty()||group.length()>30||note.length()>2000)throw new IllegalArgumentException("地点字段过长");if(ids.add(id))pins.add(new MapPins.Pin(id,name,lat,lon,group,note,p.optInt("color",0xff2d5be3)));}return pins;}
 public synchronized int importFavorites(List<MapPins.Pin> pins){SQLiteDatabase d=getWritableDatabase();int added=0;d.beginTransaction();try{for(MapPins.Pin p:pins){try(Cursor c=d.rawQuery("SELECT id FROM favorites WHERE id=?",new String[]{p.id})){if(c.moveToFirst())continue;}put(d,p);added++;}d.setTransactionSuccessful();}finally{d.endTransaction();}return added;}
 public static final class Saved {public final String id,name;public final long updated;Saved(String a,String b,long c){id=a;name=b;updated=c;}}
 public String saveRoute(String id,String name,RouteModel r)throws Exception{if(name.trim().isEmpty()||name.length()>60)throw new IllegalArgumentException("请填写路线名称");if(id==null)id=UUID.randomUUID().toString();ContentValues v=new ContentValues();v.put("id",id);v.put("name",name.trim());v.put("model",RouteCodec.encode(r));JSONObject draft=new JSONObject();android.content.SharedPreferences prefs=context.getSharedPreferences("navigation",0);draft.put("origin",prefs.getString("origin",""));draft.put("destination",prefs.getString("destination",""));draft.put("via",prefs.getString("route_via","[]"));v.put("draft",draft.toString());v.put("updated",System.currentTimeMillis());getWritableDatabase().insertWithOnConflict("routes",null,v,SQLiteDatabase.CONFLICT_REPLACE);return id;}
 public List<Saved> routes(){ArrayList<Saved>a=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT id,name,updated FROM routes ORDER BY updated DESC",null)){while(c.moveToNext())a.add(new Saved(c.getString(0),c.getString(1),c.getLong(2)));}return a;}
 public RouteModel route(String id)throws Exception{try(Cursor c=getReadableDatabase().rawQuery("SELECT model,name FROM routes WHERE id=?",new String[]{id})){if(!c.moveToFirst())throw new IllegalArgumentException("路线不存在");return RouteCodec.decode(new JSONObject(c.getString(0)).put("name",c.getString(1)).toString());}}
 public JSONObject draft(String id)throws Exception{try(Cursor c=getReadableDatabase().rawQuery("SELECT draft FROM routes WHERE id=?",new String[]{id})){return c.moveToFirst()?new JSONObject(c.getString(0)):new JSONObject();}}
 public void renameRoute(String id,String name){if(name.trim().isEmpty()||name.length()>60)throw new IllegalArgumentException("名称需为 1～60 字");ContentValues v=new ContentValues();v.put("name",name.trim());v.put("updated",System.currentTimeMillis());getWritableDatabase().update("routes",v,"id=?",new String[]{id});}
 public void deleteRoute(String id){getWritableDatabase().delete("routes","id=?",new String[]{id});}
 public synchronized void ride(String id,String name,long started,long elapsed,double meters,boolean replay,boolean active,String trace){ContentValues v=new ContentValues();v.put("id",id);v.put("name",name);v.put("started",started);v.put("elapsed",elapsed);v.put("meters",meters);v.put("replay",replay?1:0);v.put("active",active?1:0);v.put("trace",trace);getWritableDatabase().insertWithOnConflict("rides",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 public List<JSONObject> rides(){ArrayList<JSONObject>a=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT id,name,started,elapsed,meters,replay,active FROM rides ORDER BY started DESC LIMIT 200",null)){while(c.moveToNext())try{a.add(new JSONObject().put("id",c.getString(0)).put("name",c.getString(1)).put("started",c.getLong(2)).put("elapsed",c.getLong(3)).put("meters",c.getDouble(4)).put("replay",c.getInt(5)==1).put("active",c.getInt(6)==1));}catch(Exception ignored){}}return a;}
 public String trace(String id){try(Cursor c=getReadableDatabase().rawQuery("SELECT trace FROM rides WHERE id=?",new String[]{id})){return c.moveToFirst()?c.getString(0):"[]";}}
 public void deleteRide(String id){getWritableDatabase().delete("rides","id=?",new String[]{id});}
}
